/* Kamra staff app service worker (#228): keeps the app shell and its static
   files so the SPA still opens during an outage. Served by Frappe at
   /kamra-sw.min.js (a www *.min.js is sent as-is, not rendered as a
   template), so it may control /kamra - a worker under /assets/ could not.

   Only GET requests for the shell and the built files are cached. API calls are
   never touched here: the app keeps its own copy of a few read-only screens
   (frontend/src/lib/offline.ts) and money stays online-only. */
const STATIC = "kamra-static-v1"
const SHELL = "kamra-shell-v1"
const SHELL_KEY = "/kamra"

self.addEventListener("install", () => self.skipWaiting())

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keep = new Set([STATIC, SHELL])
    for (const name of await caches.keys()) if (!keep.has(name)) await caches.delete(name)
    await self.clients.claim()
  })())
})

self.addEventListener("fetch", (event) => {
  const req = event.request
  if (req.method !== "GET") return
  const url = new URL(req.url)
  if (url.origin !== self.location.origin) return

  // the boot page: always fresh when online (it carries the session's CSRF
  // token); the last good copy when the server can't be reached
  if (req.mode === "navigate" && url.pathname.startsWith("/kamra")) {
    event.respondWith((async () => {
      try {
        const res = await fetch(req)
        const html = (res.headers.get("content-type") || "").includes("text/html")
        if (res.ok && !res.redirected && html) {
          const cache = await caches.open(SHELL)
          await cache.put(SHELL_KEY, res.clone())
        }
        return res
      } catch (err) {
        const kept = await caches.match(SHELL_KEY)
        if (kept) return kept
        throw err
      }
    })())
    return
  }

  // Vite's build files have a content hash in their name: a cached copy is
  // always right. ponytail: old releases' files stay in the cache until the
  // browser evicts it; bump STATIC if that ever matters.
  if (url.pathname.startsWith("/assets/kamra/frontend/assets/")) {
    event.respondWith((async () => {
      const cache = await caches.open(STATIC)
      const kept = await cache.match(req)
      if (kept) return kept
      const res = await fetch(req)
      if (res.ok) await cache.put(req, res.clone())
      return res
    })())
  }
})

// the page lists the built files it loaded before this worker took over
// (they never passed through it), so an offline reload still finds them
self.addEventListener("message", (event) => {
  const urls = (event.data && event.data.cache) || []
  const own = urls.filter((u) => new URL(u, self.location.origin).pathname
    .startsWith("/assets/kamra/frontend/assets/"))
  event.waitUntil(caches.open(STATIC).then((cache) => Promise.all(own.map(async (u) => {
    if (!(await cache.match(u))) await cache.add(u).catch(() => undefined)
  }))))
})
